contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public entry: deposit an amount into c (from this contract) then call withdrawAll.
    // amount: how much ETH this test contract forwards to c.deposit
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this contract has enough ETH to forward
        require(address(this).balance >= amount);

        // perform deposit as a top-level state-changing call (even if amount == 0)
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // record balance before withdraw
        uint balBefore = address(c).balance;

        // attempt withdrawAll and record whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;

        // To observe whether the caller's credit was cleared, attempt a second withdrawAll and
        // see whether it transfers any further ETH (we detect success vs revert). We must call
        // it top-level as well. We'll perform the call and observe whether it reverts.
        bool secondReverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // General invariant asserted for all inputs and executions:
        // - If first withdraw reverted, then c's balance must be unchanged (balAfter == balBefore).
        // - If first withdraw succeeded, then c's balance decreased by at least 'amount' (balAfter <= balBefore - amount)
        //   and a subsequent withdrawAll does not transfer additional ETH (i.e., second withdraw must revert or
        //   at least not decrease c's balance further). We express the latter by requiring that if first succeeded
        //   then either secondReverted is true or balAfter == address(c).balance.
        // Combine into one assert expression.
        assert(
            (reverted && balAfter == balBefore)
            || (
                !reverted
                && balAfter <= balBefore - amount
                && (secondReverted || balAfter == address(c).balance)
            )
        );
    }

    receive() external payable {}
}

